"""First-run account creation and authenticated application settings."""
import re
import json

PAGE = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings · Bitcoin DCA Dashboard</title><link rel="icon" href="/favicon.ico"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png"><style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#121a2d;--line:#273650;--text:#ecf1ff;--muted:#9daec9;--accent:#8bafff;--section-gap:20px;--field-gap:16px}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top left,#1d2d4b,var(--bg) 65%);color:var(--text);font:15px system-ui,sans-serif;min-height:100vh}
main{max-width:1000px;margin:40px auto;padding:0 20px 40px}header{display:flex;align-items:center;gap:14px;margin-bottom:24px}header img{width:46px;height:46px}h1{font-size:26px;margin:0;overflow-wrap:anywhere}h2{font-size:20px;margin:0}h3{font-size:16px}p{margin:0;color:var(--muted);line-height:1.6}
.recovery-confirm{display:flex;gap:12px;align-items:flex-start;margin:16px 0;color:var(--text);line-height:1.5}.recovery-confirm input{flex:0 0 20px;width:20px;height:20px;min-height:20px;padding:0;margin:2px 0 0;accent-color:var(--accent)}#recoveryPanel{border-color:#e7c174;margin-bottom:var(--section-gap)}
.credential-editor{display:grid;gap:var(--field-gap);min-width:0;margin:0;padding:16px;border:1px solid var(--line);border-radius:10px}.field-description{display:block;margin-top:8px}.actions button{max-width:100%;white-space:normal}
#settingsForm{display:grid;gap:var(--section-gap)}.panel{display:grid;gap:var(--field-gap);background:#111a2c;border:1px solid var(--line);border-radius:12px;padding:20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--field-gap)}.grid>div,.field{min-width:0}
label{display:block;color:var(--muted);margin-bottom:8px;font-size:13px}input,select{height:48px;width:100%;min-width:0;max-width:100%;background:#0d1525;border:1px solid var(--line);color:var(--text);border-radius:9px;padding:12px;font:inherit}input:focus,select:focus{outline:2px solid var(--accent)}input,select,button,.button{min-height:44px}.hint{color:var(--muted);font-size:12px;line-height:1.6}
button,.button{background:var(--accent);color:#0b1730;border:1px solid transparent;border-radius:9px;padding:11px 16px;font:600 14px system-ui;cursor:pointer;text-decoration:none;display:inline-block;transition:box-shadow .2s}button:hover,.button:hover{box-shadow:0 0 18px #8bafff65}button:disabled{opacity:.5;cursor:wait}.secondary{background:#101a2d;border-color:var(--line);color:var(--text)}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.actions.end{justify-content:flex-end}
#status{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px 0;min-height:24px}#status.error,.inline-status.is-error{color:#ffacac}[hidden]{display:none!important}.connection-check{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.connection-check button{flex:0 0 auto}.inline-status{flex:1 1 200px;min-width:0;font-size:13px;overflow-wrap:anywhere}
.option-card{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:104px;padding:16px;margin:0;border:1px solid var(--line);border-radius:10px;background:#0d1525;cursor:pointer;color:var(--text)}.option-card span{min-width:0}.option-card strong{display:block;font-size:14px;font-weight:600;line-height:1.5}.option-card small{display:block;margin-top:5px;font-size:12px;line-height:1.5;color:var(--muted)}.option-card:focus-within{outline:2px solid var(--accent);outline-offset:2px}
.option-card input[type=checkbox]{appearance:none;-webkit-appearance:none;position:relative;flex:0 0 46px;width:46px;height:26px;min-height:26px;margin:0;padding:0;border-radius:999px;background:#34415a;border:1px solid #52617a;cursor:pointer;transition:background .18s}.option-card input[type=checkbox]::after{content:"";position:absolute;left:3px;top:3px;width:18px;height:18px;border-radius:50%;background:#ecf1ff;transition:transform .18s}.option-card input[type=checkbox]:checked{background:var(--accent);border-color:var(--accent)}.option-card input[type=checkbox]:checked::after{transform:translateX(20px);background:#10203e}.currency-card{display:grid;gap:8px;align-content:center;cursor:default}.currency-card label{margin:0;font-size:14px;font-weight:600;color:var(--text)}
.display-currency-card{display:flex;align-items:center;gap:16px}.display-currency-card>.field{flex:1;min-width:0}.display-currency-card select{flex:0 0 132px;width:132px;max-width:60%;margin-left:auto}
dialog{max-width:600px;width:calc(100% - 32px);max-height:calc(100dvh - 32px);overflow:auto;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:12px;padding:24px}dialog::backdrop{background:#060b17aa;backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px)}dialog h2{margin-bottom:16px}dialog p{margin:16px 0}dialog dl{display:grid;grid-template-columns:1fr 1fr;gap:10px}dialog dd{margin:0;overflow-wrap:anywhere}dialog dt{color:var(--muted)}
.embedded{background:var(--panel);min-height:0}.embedded main{max-width:none;margin:0;padding:20px}.embedded header,.embedded #settingsForm>.actions:first-child{display:none}.embedded .panel{background:#10182a}
@media(max-width:600px){:root{--section-gap:16px;--field-gap:14px}main{padding:0 12px 24px;margin-top:22px}header{gap:10px;margin-bottom:20px}header img{width:40px;height:40px}h1{font-size:21px}.grid{grid-template-columns:minmax(0,1fr)}.panel{padding:16px}h2{font-size:18px}input,select{font-size:16px}.embedded main{padding:16px 12px}.option-card{min-height:100px;padding:14px}.connection-check{align-items:flex-start}.inline-status{flex-basis:100%}.actions.end button{flex:1 1 auto}}
@media(max-width:420px){dialog{padding:18px}dialog dl{grid-template-columns:minmax(0,1fr)}dialog dd{margin-bottom:6px}}
@media(prefers-reduced-motion:reduce){button,.button,.option-card input[type=checkbox],.option-card input[type=checkbox]::after{transition:none}}
.review-list{margin:0}dialog .review-list{display:grid;grid-template-columns:minmax(0,1fr);gap:0}.review-list dt{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 12px 6px;font-size:13px;color:var(--text);border:1px solid var(--line);border-bottom:0;border-radius:9px 9px 0 0}.review-list dd{margin:0 0 12px;padding:0 12px 12px;border:1px solid var(--line);border-top:0;border-radius:0 0 9px 9px}.review-list .review-changed{background:#8bafff0c;border-color:#8bafff65}.review-badge{font-size:11px;color:var(--accent);white-space:nowrap}.review-comparison{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px;align-items:center}.review-side{min-width:0;overflow-wrap:anywhere}.review-caption{display:block;color:var(--muted);font-size:11px;margin-bottom:4px}.review-old{color:var(--muted)}.review-new{color:var(--accent);font-weight:600}.review-arrow{color:var(--muted)}.review-unchanged{color:var(--muted)}#unchangedReview{margin:4px 0 16px}#unchangedReview summary{cursor:pointer;font-size:13px;color:var(--muted);padding:8px 0}#unchangedReview[open] summary{margin-bottom:8px}@media(max-width:360px){.review-comparison{gap:6px;font-size:13px}}
</style></head><body><main><header><img src="/bitcoin-dca-icon-v3.png" alt=""><h1>Bitcoin DCA Dashboard</h1></header>
<section id="accountPanel" class="panel" hidden><h2>1. Create your account</h2><p>Create your dashboard credentials to continue with configuration.</p><form id="accountForm"><div class="grid"><div><label for="newUsername">Username</label><input id="newUsername" autocomplete="username" minlength="3" maxlength="64" required></div><div><label for="newPassword">Password</label><input id="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></div><div><label for="confirmPassword">Confirm password</label><input id="confirmPassword" type="password" autocomplete="new-password" minlength="12" required></div></div><p class="hint">Use at least 12 characters. No default account is created.</p><button>Create account and continue</button></form></section>
<section id="recoveryPanel" class="panel" hidden><h2>Account recovery required</h2><p>Scheduling state is missing. Your saved settings and recorded activity are retained; purchases and withdrawals are paused.</p><p class="hint">Restore a volume backup if available. Otherwise check the exchange’s orders, recent fills and Bitcoin withdrawals. Lost in-flight requests and unrecorded executions cannot be reconstructed automatically.</p><form id="recoveryForm"><div class="grid"><div><label for="recoveryPassword">Current dashboard password</label><input id="recoveryPassword" type="password" autocomplete="current-password" required></div></div><label class="recovery-confirm"><input id="recoveryConfirmed" type="checkbox" required>I checked the exchange and no order or withdrawal outcome remains unresolved.</label><div class="connection-check"><button id="recoverAccount" type="submit">Check exchange and resume bot</button><p id="recoveryFeedback" class="inline-status" role="status" aria-live="polite"></p></div></form></section>
<form id="settingsForm" hidden>
<div class="actions"><a href="/" class="button secondary" id="back">Back to dashboard</a><h2 id="pageHeading">Settings</h2></div>
<!--dashboard-credentials-start--><section id="dashboardCredentials" class="panel"><h2>Dashboard Credentials</h2><div class="actions"><button id="editDashboardCredentials" type="button" class="secondary" aria-expanded="false" aria-controls="dashboardEditor">Change dashboard credentials</button></div><p id="passwordRequired" class="hint" hidden>Open the credential editor to change the initial password before saving.</p><fieldset id="dashboardEditor" class="credential-editor" aria-labelledby="editDashboardCredentials" hidden disabled><div class="grid"><div><label for="username">Username</label><input id="username" autocomplete="username" minlength="3" maxlength="64" required></div><div><label for="current_password">Current password (for account changes)</label><input id="current_password" type="password" autocomplete="current-password"></div><div><label for="password">New password (leave empty to keep)</label><input id="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024"></div><div><label for="passwordConfirm">Confirm new password</label><input id="passwordConfirm" type="password" autocomplete="new-password"></div></div><p class="hint">Changes apply after Review and save. Closing this editor discards these edits.</p></fieldset></section><!--dashboard-credentials-end-->
<section id="exchangeConnection" class="panel"><h2>Exchange and connection</h2><div class="grid"><div><label for="exchange">Exchange</label><select id="exchange" data-setting><option>KRAKEN</option><option>BITVAVO</option></select></div><div><label for="quote">Purchase currency</label><select id="quote" data-setting><option>EUR</option><option>USD</option></select></div></div><p id="exchangeSwitchHint" class="hint" role="status" aria-live="polite" hidden></p><div class="actions"><button id="editExchangeCredentials" type="button" class="secondary" aria-expanded="false" aria-controls="exchangeEditor">Edit API access and withdrawal target</button></div><fieldset id="exchangeEditor" class="credential-editor" aria-labelledby="editExchangeCredentials" hidden disabled><h3 id="exchangeEditorTitle">Exchange API access and withdrawal target</h3><p id="exchangeCredentialHint" class="hint">Leave API fields empty to keep saved keys for the current exchange.</p><p class="hint">Use balance and trading permissions; add withdrawal permission only if needed.</p><div id="credentials" class="grid"></div><div class="grid"><div id="krakenTarget"><label for="kraken_withdraw_key">Kraken saved Bitcoin withdrawal method</label><input id="kraken_withdraw_key" data-setting></div><div id="bitvavoTarget"><label for="withdraw_address">Bitvavo Bitcoin address</label><input id="withdraw_address" data-setting></div><div id="bitvavoNetwork"><label for="withdraw_network">Bitvavo Bitcoin network</label><input id="withdraw_network" data-setting></div></div><p class="hint">Withdrawals require live trading, withdrawal permission and a saved Bitcoin destination. Changes apply after Review and save; closing this editor discards these edits.</p></fieldset><div class="connection-check"><button id="testConnection" type="button" class="secondary" aria-describedby="connectionStatus">Test connection</button><p id="connectionStatus" class="inline-status" role="status" aria-live="polite"></p></div><p class="hint">Test saved access, or open the editor to test new keys. No orders or withdrawals are submitted.</p></section>
<section id="botConfiguration" class="panel"><h2>Bot Configuration</h2><div class="grid" id="purchaseFields"></div></section>
<section id="dashboardOptions" class="panel"><h2>Trading and dashboard</h2><div class="grid feature-grid">
<label class="option-card" for="live"><span><strong>Enable live trading</strong><small>Place real Bitcoin orders. Disabled means dry run.</small></span><input id="live" type="checkbox" role="switch" data-setting></label>
<label class="option-card" for="withdrawals_enabled"><span><strong>Automatic withdrawals</strong><small>Withdraw when the configured threshold is reached.</small></span><input id="withdrawals_enabled" type="checkbox" role="switch" data-setting></label>
<label class="option-card" for="manual_withdrawal_enabled"><span><strong>Manual withdrawals</strong><small>Show the withdrawal button and require confirmation.</small></span><input id="manual_withdrawal_enabled" type="checkbox" role="switch" data-setting></label>
<label class="option-card" for="parqet_enabled"><span><strong>Parqet CSV export</strong><small>Show and allow exports of confirmed withdrawal cycles.</small></span><input id="parqet_enabled" type="checkbox" role="switch" data-setting></label>
<div class="option-card currency-card display-currency-card"><div class="field"><label for="display_currency">Display currency</label><small id="displayCurrencyHint" class="hint">Display currency affects reporting only; purchases use the purchase currency.</small></div><select id="display_currency" data-setting aria-describedby="displayCurrencyHint"><option value="EUR">Euro (EUR)</option><option value="USD">US Dollar (USD)</option></select></div>
<div class="option-card currency-card"><label for="timezone">Timezone</label><select id="timezone" data-setting aria-describedby="timezoneHint"></select><small id="timezoneHint" class="hint">Used for deposit days and schedule times; daylight saving changes are automatic.</small></div>
</div><p class="hint">These options also control the dashboard buttons and notes.</p></section>
<div class="actions end"><button id="save" type="submit">Review and save</button></div></form>
<p id="status" role="status" aria-live="polite"></p>
<dialog id="review" aria-labelledby="reviewTitle" aria-describedby="reviewDescription"><h2 id="reviewTitle">Confirm configuration</h2><p id="reviewDescription" class="hint" role="status"></p><dl id="reviewValues" class="review-list"></dl><details id="unchangedReview"><summary id="unchangedReviewTitle">Unchanged settings</summary><dl id="unchangedReviewValues" class="review-list"></dl></details><p>Settings are saved in the container’s persistent data directory. Changes take effect without rebuilding the container.</p><div class="actions end"><button type="button" class="secondary" id="cancel">Cancel</button><button type="button" id="confirm">Save configuration</button></div></dialog>
</main><script>
const initial=__INITIAL__, $=id=>document.getElementById(id);let pending=null;
function connectionMessage(text,error=false){$('connectionStatus').textContent=text;$('connectionStatus').classList.toggle('is-error',error)}
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
async function request(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-DCA-Action':'settings'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function exchangeChanged(){return $('exchange').value!==(initial.settings.exchange||'KRAKEN')}
function exchangeName(){return $('exchange').value==='KRAKEN'?'Kraken':'Bitvavo'}
function updateExchangeGuidance(){
 const changed=exchangeChanged(),name=exchangeName();
 $('exchangeSwitchHint').hidden=!changed;
 $('exchangeSwitchHint').textContent=changed?'Switching to '+name+' requires entering its API key and API secret again. Open the API access editor and review its withdrawal target.':'';
 $('exchangeEditorTitle').textContent=name+' API access and withdrawal target';
 $('exchangeCredentialHint').textContent=changed?'Enter the API key and API secret for '+name+'. Saved keys from either exchange are not reused automatically. Confirm the '+name+' withdrawal target if you use withdrawals.':'Leave API fields empty to keep saved '+name+' keys. The withdrawal target below applies to '+name+'.';
 $('editExchangeCredentials').textContent=$('exchangeEditor').hidden?(changed?'Configure '+name+' API access and withdrawal target':'Edit '+name+' API access and withdrawal target'):'Close '+name+' API access editor';
 for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret']){const input=$(prefix+'_api_'+part),active=prefix===$('exchange').value.toLowerCase();input.required=changed&&active;input.placeholder=changed&&active?'Required for '+name:(initial.settings[input.id+'_configured']?'Saved · leave empty to keep':'Not configured')}
}
function updatePurchaseCurrencyLabel(){$('withdraw_thresholdLabel').textContent='Automatic withdrawal threshold ('+($('quote').value||'EUR')+')'}
function selectedExchange(){const kraken=$('exchange').value==='KRAKEN';for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret'])$(prefix+'_api_'+part).parentElement.hidden=(prefix==='kraken')!==kraken;$('krakenTarget').hidden=!kraken;$('bitvavoTarget').hidden=kraken;$('bitvavoNetwork').hidden=kraken;$('quote').options[1].disabled=!kraken;if(!kraken)$('quote').value='EUR';updateExchangeGuidance();updatePurchaseCurrencyLabel()}
function exchangeCredentialsReady(){if(!exchangeChanged())return true;const prefix=$('exchange').value.toLowerCase();if($('exchangeEditor').hidden||!$(prefix+'_api_key').value.trim()||!$(prefix+'_api_secret').value.trim()){connectionMessage('Open Configure '+exchangeName()+' API access and enter its API key and API secret before testing or saving.',true);return false}return true}

for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret']){const key=prefix+'_api_'+part,field=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input');label.htmlFor=key;label.textContent=prefix[0].toUpperCase()+prefix.slice(1)+' API '+part;input.id=key;input.type='password';input.autocomplete='off';input.dataset.setting='';input.placeholder=initial.settings[key+'_configured']?'Saved · leave empty to keep':'Not configured';field.append(label,input);$('credentials').append(field)}
const fields=[
 ['buy_amount','BTC per purchase (0 = exchange minimum)','0','any',null,'Bitcoin amount per order. Zero uses the exchange minimum; smaller amounts are raised to that minimum.'],
 ['deposit_day','Deposit day (day of month)','1','1','31','Monthly scheduling boundary. Shorter months use their last day. The bot does not initiate deposits.'],
 ['startup_delay_seconds','Startup delay (seconds)','0','1','86400','Wait after startup or first setup before checking the account and calculating purchases.'],
 ['check_interval_seconds','Account check interval (seconds)','60','1','86400','How often balances, the purchase schedule and automatic withdrawal eligibility are checked while waiting.'],
 ['order_status_check_seconds','Open order check interval (seconds)','1','1','3600','Wait before and between checks of a submitted buy order. Unresolved orders block further buys.'],
 ['withdraw_threshold','Automatic withdrawal threshold (purchase currency)','0.01','any',null,'Withdraw when all available exchange BTC reaches this value in the purchase currency. Requires automatic withdrawals and live trading.']
];
for(const [key,title,min,step,max,description] of fields){const field=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),hint=document.createElement('small');label.htmlFor=key;label.id=key+'Label';label.textContent=title;input.id=key;input.type='number';input.required=true;input.dataset.setting='';input.min=min;input.step=step;if(max)input.max=max;hint.id=key+'Hint';hint.className='hint field-description';hint.textContent=description;input.setAttribute('aria-describedby',hint.id);field.append(label,input,hint);$('purchaseFields').append(field)}
const exchangeEditorFields=new Set(['kraken_api_key','kraken_api_secret','bitvavo_api_key','bitvavo_api_secret','kraken_withdraw_key','withdraw_address','withdraw_network']);
function setExchangeEditor(open){$('exchangeEditor').hidden=!open;$('exchangeEditor').disabled=!open;$('editExchangeCredentials').setAttribute('aria-expanded',String(open));$('editExchangeCredentials').textContent=open?'Close API access editor':'Edit API access and withdrawal target';if(!open){for(const key of exchangeEditorFields)$(key).value=key.includes('_api_')?'':(initial.settings[key]||'')}updateExchangeGuidance()}
function setDashboardEditor(open){if(!showCredentials)return;$('dashboardEditor').hidden=!open;$('dashboardEditor').disabled=!open;$('editDashboardCredentials').setAttribute('aria-expanded',String(open));$('editDashboardCredentials').textContent=open?'Close credential editor':'Change dashboard credentials';if(!open){$('username').value=initial.username||'';for(const key of ['current_password','password','passwordConfirm'])$(key).value=''}}
const timezoneGroups=[
 ['Universal',[['UTC','UTC']]],
 ['Europe',[['Europe/Berlin','Berlin'],['Europe/London','London'],['Europe/Paris','Paris'],['Europe/Zurich','Zurich'],['Europe/Helsinki','Helsinki'],['Europe/Istanbul','Istanbul'],['Europe/Moscow','Moscow']]],
 ['Americas',[['America/New_York','New York'],['America/Chicago','Chicago'],['America/Denver','Denver'],['America/Los_Angeles','Los Angeles'],['America/Anchorage','Anchorage'],['Pacific/Honolulu','Honolulu'],['America/Toronto','Toronto'],['America/Mexico_City','Mexico City'],['America/Sao_Paulo','São Paulo'],['America/Argentina/Buenos_Aires','Buenos Aires']]],
 ['Africa',[['Africa/Cairo','Cairo'],['Africa/Lagos','Lagos'],['Africa/Johannesburg','Johannesburg']]],
 ['Asia',[['Asia/Dubai','Dubai'],['Asia/Kolkata','Kolkata'],['Asia/Bangkok','Bangkok'],['Asia/Singapore','Singapore'],['Asia/Shanghai','Shanghai'],['Asia/Tokyo','Tokyo'],['Asia/Seoul','Seoul']]],
 ['Oceania',[['Australia/Perth','Perth'],['Australia/Sydney','Sydney'],['Pacific/Auckland','Auckland']]]
];
const timezoneValues=new Set();for(const [region,zones] of timezoneGroups){const group=document.createElement('optgroup');group.label=region;for(const [value,label] of zones){const option=document.createElement('option');option.value=value;option.textContent=label+' ('+value+')';group.append(option);timezoneValues.add(value)}$('timezone').append(group)}
const savedTimezone=initial.settings.timezone;if(typeof savedTimezone==='string'&&!timezoneValues.has(savedTimezone)){const option=document.createElement('option');option.value=savedTimezone;option.textContent=savedTimezone+' (saved timezone)';$('timezone').append(option)}
for(const input of document.querySelectorAll('[data-setting]')){const v=initial.settings[input.id];if(v===undefined)continue;if(input.type==='checkbox')input.checked=v;else input.value=v}
$('recoveryPanel').hidden=!initial.recoveryRequired;
$('accountPanel').hidden=!initial.createAccount;$('settingsForm').hidden=initial.createAccount;
const showCredentials=Boolean($('dashboardCredentials'));if(showCredentials)$('username').value=initial.username||'';if(!initial.complete){$('pageHeading').textContent='2. Configure your bot';$('back').hidden=true}
if(showCredentials){$('passwordRequired').hidden=!initial.passwordChangeRequired;if(initial.passwordChangeRequired){$('password').required=true;$('current_password').required=true}}
setExchangeEditor(false);$('editExchangeCredentials').addEventListener('click',()=>setExchangeEditor($('exchangeEditor').hidden));if(showCredentials){setDashboardEditor(false);$('editDashboardCredentials').addEventListener('click',()=>setDashboardEditor($('dashboardEditor').hidden))}
if(initial.embedded){
 document.body.classList.add('embedded');$('back').hidden=true;$('pageHeading').hidden=true;
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('review').open)window.parent.postMessage({type:'dca-settings-close'},location.origin)});
}
$('quote').addEventListener('change',updatePurchaseCurrencyLabel);selectedExchange();$('exchange').addEventListener('change',()=>{for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret'])$(prefix+'_api_'+part).value='';connectionMessage('');selectedExchange()});
function values(){const result={};for(const input of document.querySelectorAll('[data-setting]')){if(exchangeEditorFields.has(input.id)&&$('exchangeEditor').hidden)continue;result[input.id]=input.type==='checkbox'?input.checked:input.type==='number'&&['deposit_day','startup_delay_seconds','check_interval_seconds','order_status_check_seconds'].includes(input.id)?Number(input.value):input.value}return result}
$('recoveryForm').addEventListener('submit',async e=>{e.preventDefault();const feedback=$('recoveryFeedback');if(!$('recoveryConfirmed').checked){feedback.textContent='Confirm that you checked the exchange first.';return}const button=$('recoverAccount');button.disabled=true;feedback.classList.toggle('is-error',false);feedback.textContent='Checking exchange orders and withdrawals…';try{await request('/api/settings/recover',{current_password:$('recoveryPassword').value,confirmed:true});if(initial.embedded)window.parent.postMessage({type:'dca-settings-saved'},location.origin);else location.href='/'}catch(error){feedback.textContent=error.message;feedback.classList.add('is-error')}finally{$('recoveryPassword').value='';button.disabled=false}});
$('accountForm').addEventListener('submit',async e=>{e.preventDefault();if($('newPassword').value!==$('confirmPassword').value){message('Passwords do not match.',true);return}const b=e.submitter;b.disabled=true;try{await request('/api/setup/account',{username:$('newUsername').value,password:$('newPassword').value});location.href='/settings'}catch(err){message(err.message,true)}finally{b.disabled=false}});
$('testConnection').addEventListener('click',async()=>{if(!exchangeCredentialsReady())return;const b=$('testConnection');b.disabled=true;b.ariaBusy='true';b.textContent='Testing…';connectionMessage('Testing connection…');try{connectionMessage((await request('/api/settings/test',values())).message)}catch(err){connectionMessage(err.message,true)}finally{b.disabled=false;b.ariaBusy='false';b.textContent='Test connection'}});
function renderReview(){
 const before=initial.settings,after={...before,...pending.settings},rows=[];
 const number=value=>Number.isFinite(Number(value))?String(Number(value)):String(value??'');
 const enabled=value=>value?'Enabled':'Disabled';
 function add(name,oldValue,newValue,changed=oldValue!==newValue){rows.push({name,before:String(oldValue||'Not configured'),after:String(newValue||'Not configured'),changed:!initial.complete||changed})}
 add('Exchange',before.exchange,after.exchange);
 add('Purchase currency',before.quote,after.quote);
 for(const prefix of ['kraken','bitvavo'])for(const part of ['key','secret']){
  const key=prefix+'_api_'+part,entered=typeof pending.settings[key]==='string'&&pending.settings[key].trim()!=='';
  if(prefix!==after.exchange.toLowerCase()&&!entered)continue;
  const configured=Boolean(before[key+'_configured']),oldValue=configured?'Configured (hidden)':'Not configured';
  add((prefix==='kraken'?'Kraken':'Bitvavo')+' API '+part,oldValue,entered?'Will be updated (hidden)':oldValue,entered);
 }
 const target=settings=>settings.exchange==='KRAKEN'?'Kraken · '+(settings.kraken_withdraw_key||'Not configured'):'Bitvavo · '+(settings.withdraw_address||'Not configured')+' · '+(settings.withdraw_network||'BTC');
 add('Withdrawal target',target(before),target(after));
 for(const [key,label] of [['buy_amount','BTC per purchase'],['deposit_day','Deposit day'],['startup_delay_seconds','Startup delay'],['check_interval_seconds','Account check interval'],['order_status_check_seconds','Open order check interval'],['withdraw_threshold','Automatic withdrawal threshold']]){
  const format=(settings)=>key==='buy_amount'?(Number(settings[key])===0?'Exchange minimum':number(settings[key])+' BTC'):key==='withdraw_threshold'?number(settings[key])+' '+settings.quote:number(settings[key])+(key.endsWith('_seconds')?' seconds':'');
  add(label,format(before),format(after));
 }
 add('Live trading',before.live?'LIVE — real orders':'Dry run',after.live?'LIVE — real orders':'Dry run');
 for(const [key,label] of [['withdrawals_enabled','Automatic withdrawals'],['manual_withdrawal_enabled','Manual withdrawals'],['parqet_enabled','Parqet CSV']])add(label,enabled(before[key]),enabled(after[key]));
 add('Display currency',before.display_currency,after.display_currency);
 add('Timezone',before.timezone,after.timezone);
 if('username'in pending)add('Dashboard username',initial.username,pending.username.trim());
 if(pending.password)add('Dashboard password','Configured (hidden)','Will be changed (hidden)',true);
 $('reviewValues').replaceChildren();$('unchangedReviewValues').replaceChildren();$('unchangedReview').open=false;
 const changed=rows.filter(row=>row.changed).length;
 $('reviewDescription').textContent=!initial.complete?'New configuration — review the settings below.':changed?changed+' change'+(changed===1?'':'s')+' — compare Before and After.':'No changes. Your current settings will be retained.';
 $('unchangedReview').hidden=changed===rows.length;$('unchangedReviewTitle').textContent='Unchanged settings ('+(rows.length-changed)+')';
 for(const row of rows){
  const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=row.name;
  if(row.changed){
   dt.className='review-changed';dd.className='review-changed';const badge=document.createElement('span');badge.className='review-badge';badge.textContent=initial.complete?'Changed':'New';dt.append(badge);
   const comparison=document.createElement('div');comparison.className='review-comparison';
   function side(caption,value,className){const box=document.createElement('div'),label=document.createElement('span'),text=document.createElement('span');box.className='review-side';label.className='review-caption';label.textContent=caption;text.className=className;text.textContent=value;box.append(label,text);return box}
   if(initial.complete){const arrow=document.createElement('span');arrow.className='review-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent='→';comparison.append(side('Before',row.before,'review-old'),arrow)}
   else comparison.style.gridTemplateColumns='minmax(0,1fr)';
   comparison.append(side(initial.complete?'After':'New setting',row.after,'review-new'));dd.append(comparison);
  }else{dt.className='review-unchanged';dd.className='review-unchanged';dd.textContent=row.after}
  $(row.changed?'reviewValues':'unchangedReviewValues').append(dt,dd);
 }
}
$('settingsForm').addEventListener('submit',e=>{e.preventDefault();if(!exchangeCredentialsReady())return;const editingCredentials=showCredentials&&!$('dashboardEditor').hidden;if(initial.passwordChangeRequired&&!editingCredentials){message('Open Change dashboard credentials to update the initial password before saving.',true);return}if(editingCredentials&&$('password').value!==$('passwordConfirm').value){message('New passwords do not match.',true);return}pending={settings:values()};if(editingCredentials)Object.assign(pending,{username:$('username').value.trim(),password:$('password').value,current_password:$('current_password').value});renderReview();$('review').showModal()});

function logSettingsCancellation(){fetch('/api/ui-events',{method:'POST',headers:{'Content-Type':'application/json','X-DCA-Action':'ui-event'},body:JSON.stringify({event:'settings_save_cancelled'}),keepalive:true}).catch(()=>{})}
$('cancel').addEventListener('click',()=>{$('review').close();pending=null;logSettingsCancellation()});$('review').addEventListener('cancel',()=>{pending=null;logSettingsCancellation()});
$('confirm').addEventListener('click',async()=>{if(!pending)return;const b=$('confirm');b.disabled=true;try{const d=await request('/api/settings',pending);pending=null;if(initial.embedded){window.parent.postMessage({type:'dca-settings-saved'},location.origin)}else{location.href='/'}}catch(err){$('review').close();message(err.message,true)}finally{b.disabled=false}});
</script></body></html>'''


def settings_page(store, create_account=False, embedded=False, recovery_required=False):
    # The unauthenticated first step must not expose imported credentials or destinations.
    data = dict(settings={}, complete=False, username='', passwordChangeRequired=False) if create_account else store.public()
    data['createAccount'] = create_account
    data['embedded'] = embedded
    data['recoveryRequired'] = recovery_required
    encoded = json.dumps(data).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    page = PAGE
    if not data['complete'] and not data['passwordChangeRequired']:
        page = re.sub(r'<!--dashboard-credentials-start-->.*?<!--dashboard-credentials-end-->', '', page, flags=re.S)
    return page.replace('__INITIAL__', encoded)
